#pragma once
#include "Wire.h"
template<>struct Wire<PT_REQUEST>;
template<>struct Wire<PT_EVENT>;
template<>struct Wire<PT_STATS>;
template<>struct Wire<PT_BATCH>;
template<>struct Wire<PT_REQUEST> {static Json Encode(const PT_REQUEST& v){Json j=Json::object();j["version"]=EncodeWire(v.version);j["size"]=EncodeWire(v.size);j["flags"]=EncodeWire(v.flags);j["reserved"]=EncodeWire(v.reserved);return j;}static void Decode(const Json& j,PT_REQUEST& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="version")DecodeWire(it.value(),v.version);else if(it.key()=="size")DecodeWire(it.value(),v.size);else if(it.key()=="flags")DecodeWire(it.value(),v.flags);else if(it.key()=="reserved")DecodeWire(it.value(),v.reserved);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
